// Rescate manual: manda el contacto al agente de su agencia como si el cliente acabara de escribir.
// - No pasa a "Sin IA" (forzar_ia) y conserva la columna de IA.
// - Si hay respuesta escrita, se envía ese texto; si está vacía, la redacta la IA.
// - Si el contacto no tiene oportunidad, el flujo principal la crea en Nuevo Lead.
const CLAVE = '****';
const RUTAS = { 'Independencia': 'rsindependencia', 'Centro': 'Rscentro', 'Periodismo': 'rsperiodismov2', 'Matriz': 'rsmatriz', 'Hijar': 'Rshijar' };
const d = $json.body || $json;  // sirve para el formulario y para el webhook
const agencia = String(d.Agencia || d.agencia || '').trim();
const contactId = String(d['Contact ID'] || d.contact_id || '').trim();
const respuesta = String(d.Respuesta || d.respuesta || '').trim();
const clave = String(d.Clave || d.clave || '').trim();
if (clave !== CLAVE) throw new Error('Clave incorrecta');
const ruta = RUTAS[agencia.charAt(0).toUpperCase() + agencia.slice(1).toLowerCase()];
if (!ruta) throw new Error('Agencia no válida: ' + agencia);
if (!/^[A-Za-z0-9]{15,30}$/.test(contactId)) throw new Error('Contact ID no válido');
return [{ json: {
  url: 'http://localhost:5678/webhook/' + ruta,
  payload: { contact_id: contactId, message: { type: 19, body: String(d.mensaje_cliente || '') }, contact: {}, rescate: true, forzar_ia: true, respuesta_manual: respuesta },
  resumen: `Enviado a ${agencia} (${contactId}): ${respuesta ? 'respuesta escrita' : 'la redacta la IA'}`
} }];
